BEGIN;
SELECT plan(24);
SELECT enum_has_labels('market_lab','job_transition_state',ARRAY['pending','running','complete','failed']);
SELECT has_index('market_lab','market_snapshots','snapshot_search_gin','Market text search has a GIN index');
SELECT has_index('market_lab','source_observations','observation_entity_history','Chart history has an entity-leading covering index');
SELECT ok((SELECT relrowsecurity FROM pg_class WHERE oid='market_lab.job_transition_events'::regclass),'Transition history has row-level security');
INSERT INTO market_lab.jobs(key,kind) VALUES('pgtap-safety-rollback','fixture');
SELECT is((SELECT count(*)::int FROM market_lab.job_transition_events WHERE job_key='pgtap-safety-rollback'),1,'Insert emits one transition');
UPDATE market_lab.jobs SET available_at=now()+interval '1 second' WHERE key='pgtap-safety-rollback';
SELECT is((SELECT count(*)::int FROM market_lab.job_transition_events WHERE job_key='pgtap-safety-rollback'),1,'Unrelated updates do not fire the transition trigger');
UPDATE market_lab.jobs SET state='running' WHERE key='pgtap-safety-rollback';
SELECT is((SELECT count(*)::int FROM market_lab.job_transition_events WHERE job_key='pgtap-safety-rollback'),2,'One semantic state change emits one transition');
SELECT throws_ok($$DELETE FROM market_lab.job_transition_events WHERE job_key='pgtap-safety-rollback'$$,'42501',NULL,'Transition history is immutable by default');
SELECT throws_ok($$TRUNCATE market_lab.archives CASCADE$$,'42501',NULL,'TRUNCATE CASCADE cannot silently destroy evidence');
INSERT INTO market_lab.records(pk,sk,payload) VALUES('journal#pgtap-rollback','forecast#fixture','{"pk":"journal#pgtap-rollback","sk":"forecast#fixture","status":"pending","probability":0.6,"freeze_hash":"immutable","pending_sk":"2026-11-04"}');
SELECT throws_ok($$INSERT INTO market_lab.records(pk,sk,payload) VALUES('journal#bad-null-status','forecast#fixture','{"pk":"journal#bad-null-status","sk":"forecast#fixture","status":null}')$$,'23514',NULL,'A null status cannot pass the journal CHECK');
SELECT throws_ok($$INSERT INTO market_lab.records(pk,sk,payload) VALUES('journal#bad-missing-status','forecast#fixture','{"pk":"journal#bad-missing-status","sk":"forecast#fixture"}')$$,'23514',NULL,'A missing status cannot pass the journal CHECK');
SELECT throws_ok($$INSERT INTO market_lab.records(pk,sk,payload) VALUES('journal#bad-missing-pk','forecast#fixture','{"sk":"forecast#fixture","status":"pending"}')$$,'23514',NULL,'A missing payload owner identity is rejected');
SELECT throws_ok($$INSERT INTO market_lab.records(pk,sk,payload) VALUES('journal#bad-null-sk','forecast#fixture','{"pk":"journal#bad-null-sk","sk":null,"status":"pending"}')$$,'23514',NULL,'A null payload forecast identity is rejected');
SELECT throws_ok($$UPDATE market_lab.records SET payload=jsonb_set(payload,'{status}','null') WHERE pk='journal#pgtap-rollback'$$,'42501',NULL,'The trigger rejects a null status');
SELECT throws_ok($$UPDATE market_lab.records SET payload=payload-'status' WHERE pk='journal#pgtap-rollback'$$,'42501',NULL,'The trigger rejects removal of status');
SELECT throws_ok($$UPDATE market_lab.records SET payload=payload-'pk' WHERE pk='journal#pgtap-rollback'$$,'42501',NULL,'The trigger rejects removal of payload owner identity');
SELECT throws_ok($$UPDATE market_lab.records SET payload=jsonb_set(payload,'{sk}','null') WHERE pk='journal#pgtap-rollback'$$,'42501',NULL,'The trigger rejects null payload forecast identity');
SELECT throws_ok($$UPDATE market_lab.records SET payload=jsonb_set(payload,'{probability}','0.99') WHERE pk='journal#pgtap-rollback'$$,'42501',NULL,'A frozen prediction cannot be rewritten');
SELECT throws_ok($$DELETE FROM market_lab.records WHERE pk='journal#pgtap-rollback'$$,'42501',NULL,'A forecast cannot be silently deleted');
SELECT lives_ok($$UPDATE market_lab.records SET payload=jsonb_set(payload,'{pending_sk}','"2026-11-05"') WHERE pk='journal#pgtap-rollback'$$,'Rescheduling preserves frozen fields');
SELECT lives_ok($$UPDATE market_lab.records SET payload=(payload-'pending_sk')||'{"status":"settled","score":{"brier":0.16},"settlement_as_of":"2026-11-05"}'::jsonb WHERE pk='journal#pgtap-rollback'$$,'Settlement appends the score without rewriting the forecast');
SELECT throws_ok($$UPDATE market_lab.records SET payload=jsonb_set(payload,'{score,brier}','0') WHERE pk='journal#pgtap-rollback'$$,'42501',NULL,'A settled score cannot be rewritten');
SELECT throws_ok($$UPDATE market_lab.records SET expires_at=now()-interval '1 day' WHERE pk='journal#pgtap-rollback'$$,'42501',NULL,'Expiry cannot hide a frozen forecast');
SELECT ok(to_tsvector('english','Philadelphia 76ers win')@@websearch_to_tsquery('english','76ers'),'Full-text parser keeps team identity');
SELECT * FROM finish();
ROLLBACK;
